using UnityEngine;

/// <summary>
/// 投射物型技能效果：生成子弹/火球沿方向飞行，支持散射。
/// 右键 -> Create -> Game -> Skill Effect -> Projectile
/// </summary>
[CreateAssetMenu(fileName = "ProjectileEffect", menuName = "Game/Skill Effect/Projectile")]
public class ProjectileSkillEffect : SkillEffectBase
{
    [Header("投射物配置")]
    [Tooltip("投射物预制体（需挂载 Projectile 组件）")]
    public GameObject projectilePrefab;

    [Tooltip("飞行速度")]
    public float speed = 10f;

    [Tooltip("投射物数量（扇形散射）")]
    public int count = 1;

    [Tooltip("散射角度（仅 count > 1 时生效）")]
    [Range(0f, 180f)] public float spreadAngle = 30f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        if (projectilePrefab == null)
        {
            Debug.LogWarning("ProjectileSkillEffect: projectilePrefab 为空！");
            return;
        }

        Vector3 spawnPos = caster.CasterTransform.position;
        float baseDamage = caster.GetAttackStrength() * damageMultiplier;

        if (count == 1)
        {
            SpawnOne(spawnPos, direction, baseDamage, speed, ownerType);
        }
        else
        {
            float halfSpread = spreadAngle * 0.5f;
            float angleStep = count > 1 ? spreadAngle / (count - 1) : 0f;
            float baseAngle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;

            for (int i = 0; i < count; i++)
            {
                float angle = baseAngle - halfSpread + angleStep * i;
                Vector2 dir = new Vector2(
                    Mathf.Cos(angle * Mathf.Deg2Rad),
                    Mathf.Sin(angle * Mathf.Deg2Rad));
                SpawnOne(spawnPos, dir, baseDamage, speed, ownerType);
            }
        }
    }

    private void SpawnOne(Vector3 pos, Vector2 dir, float dmg, float spd,
                                  Projectile.OwnerType owner)
    {
        GameObject go = Instantiate(projectilePrefab, pos, Quaternion.identity);
        Projectile proj = go.GetComponent<Projectile>();
        if (proj == null) proj = go.AddComponent<Projectile>();
        proj.Initialize(dir, spd, dmg, owner);
    }
}

using System;
using UnityEngine;

/// <summary>
/// 技能运行时实例，持有 SkillData + 等级 + 冷却状态。
/// 通过 OnExecute 委托注入具体释放效果。
/// </summary>
public class SkillInstance
{
    public SkillData Data { get; private set; }
    public int Level { get; private set; } = 1;
    public int MaxLevel => Data.maxLevel;
    public bool IsMaxLevel => Level >= MaxLevel;
    public bool IsCoolingDown { get; private set; }

    private float _cooldownRemaining;

    /// <summary>剩余冷却秒数（供 UI 读取）</summary>
    public float CooldownRemaining => _cooldownRemaining;

    /// <summary>冷却进度 0~1，1=满冷却（刚释放），0=冷却完毕（供 UI 读取）</summary>
    public float CooldownPercent
    {
        get
        {
            float total = CurrentCooldown;
            return total > 0f ? Mathf.Clamp01(_cooldownRemaining / total) : 0f;
        }
    }

    /// <summary>当前等级冷却时间（每级减少10%）</summary>
    public float CurrentCooldown => Data.cooldown * (1f - (Level - 1) * 0.1f);

    /// <summary>当前等级伤害系数</summary>
    public float CurrentDamageMultiplier => Data.damageMultiplier * (1f + (Level - 1) * 0.15f);

    /// <summary>技能执行委托：参数为 (施法者, 目标方向)</summary>
    public event Action<ISkillCaster, Vector2> OnExecute;

    public SkillInstance(SkillData data)
    {
        Data = data;
        Level = 1;
    }

    /// <summary>每帧驱动冷却</summary>
    public void TickCooldown(float deltaTime)
    {
        if (!IsCoolingDown) return;
        _cooldownRemaining -= deltaTime;
        if (_cooldownRemaining <= 0f)
        {
            IsCoolingDown = false;
            _cooldownRemaining = 0f;
        }
    }

    /// <summary>尝试释放技能，返回是否成功</summary>
    public bool TryCast(ISkillCaster caster, Vector2 targetDirection)
    {
        if (IsCoolingDown) return false;

        IsCoolingDown = true;
        _cooldownRemaining = CurrentCooldown;

        OnExecute?.Invoke(caster, targetDirection);
        return true;
    }

    /// <summary>升级技能，返回是否成功</summary>
    public bool TryUpgrade()
    {
        if (IsMaxLevel) return false;
        Level++;
        return true;
    }
}

